<?php /** @var array $category @var array $items @var string $basePath */ ?>
<section class="c-page-title"><a href="<?= e_attr($basePath) ?>/menus">← All menus</a><p class="c-eyebrow">Catering menu</p><h1><?= e($category['name']) ?></h1><p><?= e($category['description']) ?></p></section>
<section class="c-wrap c-section c-menu-detail"><div class="c-menu-detail-list"><?php foreach ($items as $item): ?><article><div><h2><?= e($item['name']) ?></h2><p><?= e($item['description']) ?></p><?php if ($item['dietary'] !== ''): ?><div class="c-chips"><?php foreach (explode(',', (string) $item['dietary']) as $tag): ?><span><?= e(trim($tag)) ?></span><?php endforeach; ?></div><?php endif; ?></div><p class="c-menu-price">$<?= e(number_format(((int) $item['price_cents']) / 100, 2)) ?><small><?= e($item['price_unit']) ?></small></p></article><?php endforeach; ?></div><aside><p class="c-eyebrow">Make it yours</p><h2>Build this menu into your event.</h2><p>Tell us your date, guest count, service style, and favorite selections.</p><a class="c-button c-button-green" href="<?= e_attr($basePath) ?>/request-a-quote?menu_interest=<?= e_attr($category['name']) ?>">Request a proposal</a></aside></section>
